const output = [];

for (const item of $input.all()) {
  const json = item.json;

  // Remotive: { jobs: [...] }
  if (json && Array.isArray(json.jobs)) {
    for (const job of json.jobs) {
      output.push({
        title: job.title || "Untitled",
        company: job.company_name || "Unknown",
        url: job.url || "",
        source: "Remotive",
        tags: Array.isArray(job.tags) ? job.tags : []
      });
    }
    continue;
  }

  // RemoteOK's first array element is a legal notice, not a job - skip it
  if (json && json.legal) {
    continue;
  }

  // RemoteOK job object
  if (json && json.position && json.company) {
    output.push({
      title: json.position,
      company: json.company,
      url: json.url ? `https://remoteok.com${json.url}` : (json.apply_url || ""),
      source: "RemoteOK",
      tags: Array.isArray(json.tags) ? json.tags : []
    });
    continue;
  }


  // FIX: this branch was missing entirely, so every Jordan Government
  // job silently disappeared here regardless of the keyword filter
  if (json && json.source === "SPAC Jordan") {
    output.push({
      title: json.title || "Untitled",
      company: json.company || "Government of Jordan",
      url: json.url || "",
      source: "SPAC Jordan",
      tags: []
    });
    continue;
  }
}

return output.map(o => ({ json: o }));

const TECH_KEYWORDS = {
  roles: [
    // English Roles
    "software engineer", "software developer", "web developer", "frontend developer",
    "front-end developer", "backend developer", "back-end developer", "full stack developer",
    "full-stack developer", "qa engineer", "quality assurance", "automation engineer",
    "test engineer", "software tester",
    // Arabic Roles
    "مطور", "مبرمج", "مهندس برمجيات", "مهندس حاسوب", "مطور ويب", "مطور واجهات",
    "فحص برمجيات", "توكيد جودة", "ضبط الجودة", "أخصائي جودة", "مهندس أتمتة", "فاحص جودة", "مبرمج مساعد"
  ],
  languages: [
    "javascript", "typescript", "sql", "جافاسكربت", "تايب سكربت", "جافا سكربت"
  ],
  frontend: [
    "react", "reactjs", "react.js", "next.js", "nextjs", "html5", "css3",
    "tailwind", "tailwindcss", "رياكت"
  ],
  backend: [
    "node.js", "nodejs", "express.js", "expressjs", "postgresql", "postgres",
    "supabase", "rest api", "نود"
  ],
  testing_qa: [
    "cypress", "appium", "selenium", "postman", "jmeter", "swagger",
    "api testing", "manual testing", "automation testing", "اختبار برمجيات", "فحص الجودة"
  ],
  cloud_tools: [
    "aws", "git", "github", "figma", "cloudinary", "vercel", "apify"
  ],
  general: [
    "software", "software development", "web development", "automation", "n8n",
    "أتمتة", "برمجة", "تقنية المعلومات"
  ]
};

function escapeRegex(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

const ALL_KEYWORDS = Object.values(TECH_KEYWORDS).flat();

// FIX: plain \b only recognizes ASCII word chars, so it never matched
// around Arabic letters. \p{L}/\p{N} lookaround (with the 'u' flag)
// makes word boundaries work for Arabic too.
const KEYWORD_REGEX = new RegExp(
  '(?<![\\p{L}\\p{N}])(' + ALL_KEYWORDS.map(escapeRegex).join('|') + ')(?![\\p{L}\\p{N}])',
  'giu'
);

const results = [];

for (const item of $input.all()) {
  const job = item.json;
  const tagsText = Array.isArray(job.tags) ? job.tags.join(' ') : '';
  const searchText = `${job.title || ''} ${job.company || ''} ${tagsText}`.toLowerCase();

  const matches = searchText.match(KEYWORD_REGEX) || [];
  const uniqueMatches = [...new Set(matches.map(m => m.toLowerCase()))];
  const isTechJob = uniqueMatches.length > 0 ? 1 : 0;

  results.push({
    json: {
      ...job,
      isTechJob,
      matchedKeywords: uniqueMatches
    }
  });
}

return results.filter(r => r.json.isTechJob === 1);

// Get the raw HTML string from the previous node
const htmlString = $input.first().json.data;
const jobsMap = new Map(); // JobID -> job object, prevents duplicates

// Regex now also captures the numeric JobID separately
const regex = /<a\s+href="(JobDet\.aspx\?JobID=(\d+))">([^<]+)<\/a>/g;
let match;

while ((match = regex.exec(htmlString)) !== null) {
    const path = match[1].trim();
    const jobId = match[2];
    let fullText = match[3].trim();

    // Skip the generic "تفاصيل" (Details) link — it's a duplicate
    // of the real title link that already appears for this same JobID
    if (fullText === 'تفاصيل') {
        continue;
    }

    // The portal formats text like: "-وظائف المساندة... / محافظة جرش / وزارة الثقافه"
    // Splitting by '/' separates the Ministry (company) from the Title
    const parts = fullText.split('/');

    let company = "Government of Jordan";
    let title = fullText;
    if (parts.length > 1) {
        company = parts.pop().trim();       // last part = Ministry
        title = parts.join(' / ').trim();   // rest = job title

        if (title.startsWith('-')) {
            title = title.substring(1).trim();
        }
    }

    // Keep only the first (real) entry per JobID
    if (!jobsMap.has(jobId)) {
        jobsMap.set(jobId, {
            title: title,
            company: company,
            url: `https://applyjobs.spac.gov.jo/${path}`,
            source: "SPAC Jordan"
        });
    }
}

// Return the deduplicated array in the format n8n expects
return Array.from(jobsMap.values()).map(job => ({ json: job }));
